"""Every rounding rule of meterbill lives here.

Nothing in this module reads or changes the decimal context: Decimal values
are rounded with exact integer arithmetic.
"""

from __future__ import annotations

import math
from decimal import Decimal, InvalidOperation

CENT = Decimal("0.01")
HALF_UP = "half_up"
HALF_EVEN = "half_even"
DOWN = "down"

_METHODS = (HALF_UP, HALF_EVEN, DOWN)


def _check_method(method) -> None:
    if method not in _METHODS:
        raise ValueError(f"unknown rounding method: {method!r}")


def _check_step(step) -> None:
    if not isinstance(step, Decimal):
        raise TypeError("step must be a Decimal")
    if not step.is_finite() or step <= 0:
        raise ValueError("step must be a positive decimal")


def _parts(d: Decimal):
    sign, digits, exp = d.as_tuple()
    coef = 0
    for x in digits:
        coef = coef * 10 + x
    return sign, coef, exp


def _units(value: Decimal, step: Decimal, method: str) -> int:
    """`value` as a whole number of `step`s (signed), rounded by `method`."""
    vs, vc, ve = _parts(value)
    _, sc, se = _parts(step)
    # |value| / step = vc * 10**ve / (sc * 10**se)
    num, den = vc, sc
    if ve >= se:
        num *= 10 ** (ve - se)
    else:
        den *= 10 ** (se - ve)
    n, r = divmod(num, den)
    if method != DOWN:
        twice = 2 * r
        if twice > den or (twice == den and (method == HALF_UP or n % 2 == 1)):
            n += 1
    return -n if vs else n


def _build(units: int, step: Decimal, negative_zero: bool = False) -> Decimal:
    _, sc, se = _parts(step)
    n = units * sc
    sign = 1 if (n < 0 or (n == 0 and negative_zero)) else 0
    digits = tuple(int(c) for c in str(abs(n)))
    return Decimal((sign, digits, se))


def round_amount(value: Decimal, step: Decimal, method: str) -> Decimal:
    if not isinstance(value, Decimal) or not isinstance(step, Decimal):
        raise TypeError("value and step must be Decimal")
    _check_method(method)
    _check_step(step)
    if not value.is_finite():
        raise InvalidOperation("value must be finite")
    return _build(_units(value, step, method), step, negative_zero=bool(value.is_signed()))


def allocate(amounts: list[Decimal], step: Decimal) -> list[Decimal]:
    _check_step(step)
    zero = Decimal(0)
    cuts = [_units(a, step, DOWN) for a in amounts]
    # exact sum of the amounts, as a number of steps, half up
    total = _exact_sum(amounts)
    whole = _units(total, step, HALF_UP)
    rest = whole - sum(cuts)
    for i in range(len(cuts) - 1, -1, -1):
        if amounts[i] != zero:
            cuts[i] += rest
            break
    return [_build(u, step) for u in cuts]


def _exact_sum(amounts) -> Decimal:
    """Sum without any context rounding."""
    if not amounts:
        return Decimal(0)
    exp = min(_parts(a)[2] for a in amounts)
    total = 0
    for a in amounts:
        s, c, e = _parts(a)
        c *= 10 ** (e - exp)
        total += -c if s else c
    sign = 1 if total < 0 else 0
    return Decimal((sign, tuple(int(c) for c in str(abs(total))), exp))


def legacy_cents(value: float, places: int = 2) -> float:
    if not 0 <= places <= 6:
        raise ValueError("places must be between 0 and 6")
    scale = 10 ** places
    return math.floor(value * scale + 0.5) / scale


def fixed(value: float | Decimal, places: int, method: str = HALF_EVEN) -> str:
    if isinstance(places, bool) or not isinstance(places, int) or places < 0:
        raise ValueError("places must be a non-negative integer")
    if isinstance(value, Decimal):
        step = Decimal((0, (1,), -places))
        return format(round_amount(value, step, method), "f")
    _check_method(method)
    if method != HALF_EVEN:
        raise ValueError("a float is only written half even")
    return format(value, f".{places}f")

