import json, random, subprocess, os, sys, tempfile, shutil
random.seed(5)
def run(root, args):
    r=subprocess.run([sys.executable,"-m","meterbill",*args],cwd=root,capture_output=True,text=True)
    return r.returncode,r.stdout,r.stderr
def dec(n): return str(random.choice([random.randint(0,99999)/10**random.randint(0,5), random.randint(1,999)/1000]))
bad=0
for it in range(150):
    d=tempfile.mkdtemp()
    book={"currencies":{"EUR":{"cash":random.choice(["none","whole","0.05","0.10","5"])},"GBP":{"cash":random.choice(["none","whole","0.05"])}},"tariffs":{}}
    for n in "abc":
        ups=sorted(set(random.randint(1,300) for _ in range(2)))
        bands=[{"upto":str(u),"price":str(random.randint(1,9999)/10**random.randint(3,5))} for u in ups]+[{"upto":None,"price":str(random.randint(1,9999)/10**4)}]
        book["tariffs"][n]={"currency":random.choice(["EUR","GBP"]),"vat":random.choice(["0.21","0.055","0.2","0.125","0.0"]),"standing":str(random.randint(0,9999)/10**random.randint(2,5)),"bands":bands}
    bp=d+"/b.json"; json.dump(book,open(bp,"w"))
    os.mkdir(d+"/acc")
    for i in range(6):
        s=random.randint(1,25)
        acc={"account":f"A{i}","name":"x","tariff":random.choice("abc"),"period":{"start":"2026-03-01","end":f"2026-03-{s+3:02d}"},
         "readings":[{"meter":"M","kwh":dec(0)}],
         "credits":[{"ref":"c","amount":round(random.uniform(-30,30),random.choice([2,3,4]))} for _ in range(random.randint(0,3))]}
        if random.random()<.5: acc["standing"]=[{"from":"2026-03-01","to":f"2026-03-{s:02d}","rate":str(random.randint(-5,9999)/10**random.randint(2,5))},{"from":f"2026-03-{s+1:02d}","to":f"2026-03-{s+3:02d}","rate":str(random.randint(0,9999)/10**4)}]
        json.dump(acc,open(f"{d}/acc/a{i}.json","w"))
    cmds=[["--tariffs",bp,"tariffs"],["--tariffs",bp,"batch",d+"/acc"],["--tariffs",bp,"batch",d+"/acc","--format","csv"]]
    for i in range(6):
        for f in ("text","csv","json"): cmds.append(["--tariffs",bp,"bill",f"{d}/acc/a{i}.json","--format",f])
    for _ in range(6):
        for f in ("text","json"): cmds.append(["--tariffs",bp,"quote",random.choice("abc"),dec(0),str(random.randint(1,100)),"--format",f])
    for c in cmds:
        if run("/app",c)!=run("/tmp/opencode/orig",c): bad+=1; print("DIFF",c)
    shutil.rmtree(d)
print("bad",bad)
